type CaptionCubeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CaptionCubeBase>;

const CaptionCubeInner = forwardRef<
  HTMLDivElement,
  CaptionCubeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CaptionCube>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CaptionCubeBase
          {...(componentProps as unknown as ComponentProps<typeof CaptionCubeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CaptionCube = Interactive.withSchema({
  Component: CaptionCubeInner,
  componentName: "<CaptionCube>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
